/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
 */
@Provides(JavacASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends JavacASTAdapter {
public boolean generateFieldDefaultsForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		this.fieldDefaultType = typeNode;
		this.fieldDefaultError = errorNode;
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;


		rememberFieldDefaultState(typeNode, errorNode, level, makeFinal);
		return applyFieldDefaultsUsingRememberedState(checkForTypeLevelFieldDefaults);
	}

public void setFieldDefaultsForField(JavacNode fieldNode, AccessLevel level, boolean makeFinal) {
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;


		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.mods.flags & (Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED)) == 0) {
				if (!hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode)) {
					if ((field.mods.flags & Flags.STATIC) == 0) {
						field.mods.flags |= toJavacModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.mods.flags & Flags.FINAL) == 0) {
			if (!hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode)) {
				if ((field.mods.flags & Flags.STATIC) == 0) {
					field.mods.flags |= Flags.FINAL;
				}
			}
		}

		fieldNode.rebuild();
	}

@Override public void visitType(JavacNode typeNode, JCClassDecl type) {
		this.fieldDefaultType = typeNode;


		AnnotationValues<FieldDefaults> fieldDefaults = null;
		JavacNode source = typeNode;

		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (JavacNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			JCAnnotation ann = (JCAnnotation) jn.get();
			JCTree typeTree = ann.annotationType;
			if (typeTree == null) continue;
			String typeTreeToString = typeTree.toString();
			if (!typeTreeToString.equals("FieldDefaults") && !typeTreeToString.equals("lombok.experimental.FieldDefaults")) continue;
			if (!typeMatches(FieldDefaults.class, jn, typeTree)) continue;

			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			levelIsExplicit = fieldDefaults.isExplicit("level");
			makeFinalIsExplicit = fieldDefaults.isExplicit("makeFinal");

			handleExperimentalFlagUsage(jn, ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE, "@FieldDefaults");

			fd = fieldDefaults.getInstance();
			if (!levelIsExplicit && !makeFinalIsExplicit) {
				jn.addError("This does nothing; provide either level or makeFinal or both.");
			}

			if (levelIsExplicit && fd.level() == AccessLevel.NONE) {
				jn.addError("AccessLevel.NONE doesn't mean anything here. Pick another value.");
				levelIsExplicit = false;
			}

			deleteAnnotationIfNeccessary(jn, FieldDefaults.class);
			deleteImportFromCompilationUnit(jn, "lombok.AccessLevel");
			break;
		}

		if (fd == null && (type.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) return;

		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));

		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;

		generateFieldDefaultsForType(typeNode, source, fdAccessLevel, fdToFinal, false);
	}


	private AccessLevel fieldDefaultAccess;
	private boolean fieldDefaultMakeFinal;
	private JavacNode fieldDefaultType;
	private JavacNode fieldDefaultError;

	private JavacNode getterTypeNode;
	private JavacNode getterErrorNode;
	private AccessLevel getterLevel;
	private boolean getterCheckForTypeLevel;
	private List<JCAnnotation> getterOnMethod;
	private boolean getterLazy;

	private JavacNode setterTypeNode;
	private JavacNode setterErrorNode;
	private AccessLevel setterLevel;
	private boolean setterCheckForTypeLevel;
	private List<JCAnnotation> setterOnMethod;
	private List<JCAnnotation> setterOnParam;

	private JavacNode constructorTypeNode;
	private JavacNode constructorSourceNode;
	private AccessLevel constructorLevel;
	private String constructorStaticName;
	private HandleConstructor.SkipIfConstructorExists constructorSkipMode;

	private JavacNode toStringTypeNode;
	private JavacNode toStringErrorNode;
	private boolean toStringIncludeFieldNames;
	private FieldAccess toStringFieldAccess;

	private JavacNode valueTypeNode;
	private JavacNode valueAnnotationNode;
	private String valueStaticConstructorName;

	private JavacNode dataTypeNode;
	private JavacNode dataAnnotationNode;
	private String dataStaticConstructorName;

	private void rememberFieldDefaultState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal) {
		this.fieldDefaultType = typeNode;
		this.fieldDefaultError = errorNode;
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;
	}

	private boolean fieldDefaultTypeIsUsable() {

		return fieldDefaultType != null && fieldDefaultError != null;
	}

	private void applyRememberedFieldDefaultsToEachField() {

		if (!fieldDefaultTypeIsUsable()) return;
		for (JavacNode field : fieldDefaultType.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			if (fieldDecl.name.toString().startsWith("$")) continue;
			setFieldDefaultsForField(field, fieldDefaultAccess, fieldDefaultMakeFinal);
		}
	}

	public boolean applyFieldDefaultsUsingRememberedState(boolean checkForTypeLevelFieldDefaults) {

		if (!fieldDefaultTypeIsUsable()) return false;
		if (checkForTypeLevelFieldDefaults && hasAnnotation(FieldDefaults.class, fieldDefaultType)) return true;
		if (!isClassOrEnum(fieldDefaultType)) {
			fieldDefaultError.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}
		applyRememberedFieldDefaultsToEachField();
		return true;
	}

	private void rememberGetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;
		this.getterOnMethod = onMethod;
		this.getterLazy = false;
	}

	private boolean getterStateIsReady() {

		return getterTypeNode != null && getterErrorNode != null;
	}

	private void generateRememberedGetters() {

		if (!getterStateIsReady()) return;
		if (getterCheckForTypeLevel && hasAnnotation(Getter.class, getterTypeNode)) return;
		if (!isClassOrEnum(getterTypeNode)) {
			getterErrorNode.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}
		for (JavacNode field : getterTypeNode.down()) {
			if (fieldQualifiesForGetterGeneration(field)) {
				generateGetterForField(field, getterErrorNode.get(), getterLevel, getterLazy, getterOnMethod);
			}
		}
	}

	public void applyGetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterOnMethod = onMethod;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;


		rememberGetterState(typeNode, errorNode, level, checkForTypeLevelGetter, onMethod);
		if (getterStateIsReady()) generateRememberedGetters();
	}

	private void rememberSetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
	}

	private boolean setterStateIsReady() {

		return setterTypeNode != null && setterErrorNode != null;
	}

	private void generateRememberedSetters() {

		if (!setterStateIsReady()) return;
		generateSetterForType(setterTypeNode, setterErrorNode, setterLevel, setterCheckForTypeLevel, setterOnMethod, setterOnParam);
	}

	public void applySetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;


		rememberSetterState(typeNode, errorNode, level, checkForTypeLevelSetter, onMethod, onParam);
		if (setterStateIsReady()) generateRememberedSetters();
	}

	private void rememberConstructorState(JavacNode typeNode, AccessLevel level, String staticName, HandleConstructor.SkipIfConstructorExists skip, JavacNode source) {
		this.constructorTypeNode = typeNode;
		this.constructorLevel = level;
		this.constructorStaticName = staticName;
		this.constructorSkipMode = skip;
		this.constructorSourceNode = source;
	}

	private boolean constructorStateIsReady() {

		return constructorTypeNode != null && constructorSourceNode != null && constructorSkipMode != null;
	}

	private void generateRememberedRequiredArgsConstructor() {

		if (!constructorStateIsReady()) return;
		generateRequiredArgsConstructor(constructorTypeNode, constructorLevel, constructorStaticName, constructorSkipMode, constructorSourceNode);
	}

	private void generateRememberedAllArgsConstructor() {

		if (!constructorStateIsReady()) return;
		generateAllArgsConstructor(constructorTypeNode, constructorLevel, constructorStaticName, constructorSkipMode, constructorSourceNode);
	}

	private void generateRememberedExtraNoArgsConstructor() {

		if (constructorTypeNode == null || constructorSourceNode == null) return;
		generateExtraNoArgsConstructor(constructorTypeNode, constructorSourceNode);
	}

	public void applyRequiredArgsConstructor(JavacNode typeNode, AccessLevel level, String staticName, HandleConstructor.SkipIfConstructorExists skip, JavacNode source) {
		this.constructorTypeNode = typeNode;
		this.constructorLevel = level;
		this.constructorStaticName = staticName;
		this.constructorSkipMode = skip;
		this.constructorSourceNode = source;


		rememberConstructorState(typeNode, level, staticName, skip, source);
		if (constructorStateIsReady()) generateRememberedRequiredArgsConstructor();
	}

	public void applyAllArgsConstructor(JavacNode typeNode, AccessLevel level, String staticName, HandleConstructor.SkipIfConstructorExists skip, JavacNode source) {
		this.constructorTypeNode = typeNode;
		this.constructorLevel = level;
		this.constructorStaticName = staticName;
		this.constructorSkipMode = skip;
		this.constructorSourceNode = source;


		rememberConstructorState(typeNode, level, staticName, skip, source);
		if (constructorStateIsReady()) generateRememberedAllArgsConstructor();
	}

	private void rememberToStringState(JavacNode typeNode, JavacNode errorNode) {
		this.toStringTypeNode = typeNode;
		this.toStringErrorNode = errorNode;
		this.toStringIncludeFieldNames = true;
		this.toStringFieldAccess = FieldAccess.GETTER;
	}

	private boolean toStringStateIsReady() {

		return toStringTypeNode != null && toStringErrorNode != null;
	}

	private void generateRememberedToString() {

		if (!toStringStateIsReady()) return;
		generateToStringForType(toStringTypeNode, toStringErrorNode);
	}

	public void applyToStringGeneration(JavacNode typeNode, JavacNode errorNode) {
		this.toStringTypeNode = typeNode;
		this.toStringErrorNode = errorNode;


		rememberToStringState(typeNode, errorNode);
		if (toStringStateIsReady()) generateRememberedToString();
	}

	public void applyValueFieldAndAccessorDefaults(JavacNode typeNode, JavacNode annotationNode, String staticConstructorName) {

		this.valueTypeNode = typeNode;
		this.valueAnnotationNode = annotationNode;
		this.valueStaticConstructorName = staticConstructorName;
		if (valueTypeNode == null || valueAnnotationNode == null) return;
		generateFieldDefaultsForType(valueTypeNode, valueAnnotationNode, AccessLevel.PRIVATE, true, true);
		applyAllArgsConstructor(valueTypeNode, AccessLevel.PUBLIC, valueStaticConstructorName, HandleConstructor.SkipIfConstructorExists.YES, valueAnnotationNode);
		generateRememberedExtraNoArgsConstructor();
		applyGetterGeneration(valueTypeNode, valueAnnotationNode, AccessLevel.PUBLIC, true, List.<JCAnnotation>nil());
	}

	public void applyDataAccessorsAndConstructors(JavacNode typeNode, JavacNode annotationNode, String staticConstructorName) {

		this.dataTypeNode = typeNode;
		this.dataAnnotationNode = annotationNode;
		this.dataStaticConstructorName = staticConstructorName;
		if (dataTypeNode == null || dataAnnotationNode == null) return;
		applyRequiredArgsConstructor(dataTypeNode, AccessLevel.PUBLIC, dataStaticConstructorName, HandleConstructor.SkipIfConstructorExists.YES, dataAnnotationNode);
		generateRememberedExtraNoArgsConstructor();
		applyGetterGeneration(dataTypeNode, dataAnnotationNode, AccessLevel.PUBLIC, true, List.<JCAnnotation>nil());
		applySetterGeneration(dataTypeNode, dataAnnotationNode, AccessLevel.PUBLIC, true, List.<JCAnnotation>nil(), List.<JCAnnotation>nil());
	}

private static final String GETTER_NODE_NOT_SUPPORTED_ERR = "@Getter is only supported on a class, an enum, or a field.";

public void generateGetterForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterOnMethod = onMethod;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;


		rememberGetterState(typeNode, errorNode, level, checkForTypeLevelGetter, onMethod);
		if (checkForTypeLevelGetter) {
			if (hasAnnotation(Getter.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			errorNode.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		for (JavacNode field : typeNode.down()) {
			if (fieldQualifiesForGetterGeneration(field)) generateGetterForField(field, errorNode.get(), level, false, onMethod);
		}
	}

public boolean fieldQualifiesForGetterGeneration(JavacNode field) {
		this.getterErrorNode = field;
		if (field.getKind() != Kind.FIELD) return false;
		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		//Skip fields that start with $
		if (fieldDecl.name.toString().startsWith("$")) return false;
		//Skip static fields.
		if ((fieldDecl.mods.flags & Flags.STATIC) != 0) return false;
		return true;
	}

public void generateGetterForField(JavacNode fieldNode, DiagnosticPosition pos, AccessLevel level, boolean lazy, List<JCAnnotation> onMethod) {
		this.getterLevel = level;
		this.getterLazy = lazy;
		this.getterOnMethod = onMethod;


		if (hasAnnotation(Getter.class, fieldNode)) {
			//The annotation will make it happen, so we can skip it.
			return;
		}
		createGetterForField(level, fieldNode, fieldNode, false, lazy, onMethod);
	}

public void handleGetter(AnnotationValues<Getter> annotation, JCAnnotation ast, JavacNode annotationNode) {
		this.getterErrorNode = annotationNode;
		this.getterTypeNode = annotationNode.up();


		handleFlagUsage(annotationNode, ConfigurationKeys.GETTER_FLAG_USAGE, "@Getter");

		Collection<JavacNode> fields = annotationNode.upFromAnnotationToFields();
		deleteAnnotationIfNeccessary(annotationNode, Getter.class);
		deleteImportFromCompilationUnit(annotationNode, "lombok.AccessLevel");
		JavacNode node = annotationNode.up();
		Getter annotationInstance = annotation.getInstance();
		AccessLevel level = annotationInstance.value();
		boolean lazy = annotationInstance.lazy();
		if (lazy) handleFlagUsage(annotationNode, ConfigurationKeys.GETTER_LAZY_FLAG_USAGE, "@Getter(lazy=true)");

		if (level == AccessLevel.NONE) {
			if (lazy) annotationNode.addWarning("'lazy' does not work with AccessLevel.NONE.");
			return;
		}

		if (node == null) return;

		List<JCAnnotation> onMethod = unboxAndRemoveAnnotationParameter(ast, "onMethod", "@Getter(onMethod", annotationNode);

		switch (node.getKind()) {
		case FIELD:
			createGetterForFields(level, fields, annotationNode, true, lazy, onMethod);
			break;
		case TYPE:
			if (lazy) annotationNode.addError("'lazy' is not supported for @Getter on a type.");
			generateGetterForType(node, annotationNode, level, false, onMethod);
			break;
		}
	}

public void createGetterForFields(AccessLevel level, Collection<JavacNode> fieldNodes, JavacNode errorNode, boolean whineIfExists, boolean lazy, List<JCAnnotation> onMethod) {
		this.getterLevel = level;
		this.getterErrorNode = errorNode;
		this.getterLazy = lazy;
		this.getterOnMethod = onMethod;


		for (JavacNode fieldNode : fieldNodes) {
			createGetterForField(level, fieldNode, errorNode, whineIfExists, lazy, onMethod);
		}
	}

public void createGetterForField(AccessLevel level,
			JavacNode fieldNode, JavacNode source, boolean whineIfExists, boolean lazy, List<JCAnnotation> onMethod) {
		this.getterLevel = level;
		this.getterErrorNode = source;
		this.getterLazy = lazy;
		this.getterOnMethod = onMethod;


		if (fieldNode.getKind() != Kind.FIELD) {
			source.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		JCVariableDecl fieldDecl = (JCVariableDecl)fieldNode.get();

		if (lazy) {
			if ((fieldDecl.mods.flags & Flags.PRIVATE) == 0 || (fieldDecl.mods.flags & Flags.FINAL) == 0) {
				source.addError("'lazy' requires the field to be private and final.");
				return;
			}
			if ((fieldDecl.mods.flags & Flags.TRANSIENT) != 0) {
				source.addError("'lazy' is not supported on transient fields.");
				return;
			}
			if (fieldDecl.init == null) {
				source.addError("'lazy' requires field initialization.");
				return;
			}
		}

		String methodName = toGetterName(fieldNode);

		if (methodName == null) {
			source.addWarning("Not generating getter for this field: It does not fit your @Accessors prefix list.");
			return;
		}

		for (String altName : toAllGetterNames(fieldNode)) {
			switch (methodExists(altName, fieldNode, false, 0)) {
			case EXISTS_BY_LOMBOK:
				return;
			case EXISTS_BY_USER:
				if (whineIfExists) {
					String altNameExpl = "";
					if (!altName.equals(methodName)) altNameExpl = String.format(" (%s)", altName);
					source.addWarning(
						String.format("Not generating %s(): A method with that name already exists%s", methodName, altNameExpl));
				}
				return;
			default:
			case NOT_EXISTS:
				//continue scanning the other alt names.
			}
		}

		long access = toJavacModifier(level) | (fieldDecl.mods.flags & Flags.STATIC);

		injectMethod(fieldNode.up(), createGetter(access, fieldNode, fieldNode.getTreeMaker(), source, lazy, onMethod));
	}

public JCMethodDecl createGetter(long access, JavacNode field, JavacTreeMaker treeMaker, JavacNode source, boolean lazy, List<JCAnnotation> onMethod) {
		this.getterLazy = lazy;
		this.getterOnMethod = onMethod;


		JCVariableDecl fieldNode = (JCVariableDecl) field.get();

		// Remember the type; lazy will change it
		JCExpression methodType = cloneType(treeMaker, copyType(treeMaker, fieldNode), source);
		// Generate the methodName; lazy will change the field type
		Name methodName = field.toName(toGetterName(field));

		List<JCStatement> statements;
		JCTree toClearOfMarkers = null;
		int[] methodArgPos = null;
		boolean addSuppressWarningsUnchecked = false;
		if (lazy && !inNetbeansEditor(field)) {
			toClearOfMarkers = fieldNode.init;
			if (toClearOfMarkers instanceof JCMethodInvocation) {
				List<JCExpression> args = ((JCMethodInvocation) toClearOfMarkers).args;
				methodArgPos = new int[args.length()];
				for (int i = 0; i < methodArgPos.length; i++) {
					methodArgPos[i] = args.get(i).pos;
				}
			}
			statements = createLazyGetterBody(treeMaker, field, source);
			addSuppressWarningsUnchecked = LombokOptionsFactory.getDelombokOptions(field.getContext()).getFormatPreferences().generateSuppressWarnings();
		} else {
			statements = createSimpleGetterBody(treeMaker, field);
		}

		JCBlock methodBody = treeMaker.Block(0, statements);

		List<JCTypeParameter> methodGenericParams = List.nil();
		List<JCVariableDecl> parameters = List.nil();
		List<JCExpression> throwsClauses = List.nil();
		JCExpression annotationMethodDefaultValue = null;

		List<JCAnnotation> copyableAnnotations = findCopyableAnnotations(field);
		List<JCAnnotation> delegates = findDelegatesAndRemoveFromField(field);
		List<JCAnnotation> annsOnMethod = copyAnnotations(onMethod).appendList(copyableAnnotations);
		if (field.isFinal()) {
			if (getCheckerFrameworkVersion(field).generatePure()) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genTypeRef(field, CheckerFrameworkVersion.NAME__PURE), List.<JCExpression>nil()));
		} else {
			if (getCheckerFrameworkVersion(field).generateSideEffectFree()) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genTypeRef(field, CheckerFrameworkVersion.NAME__SIDE_EFFECT_FREE), List.<JCExpression>nil()));
		}
		if (isFieldDeprecated(field)) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genJavaLangTypeRef(field, "Deprecated"), List.<JCExpression>nil()));

		JCMethodDecl decl = recursiveSetGeneratedBy(treeMaker.MethodDef(treeMaker.Modifiers(access, annsOnMethod), methodName, methodType,
			methodGenericParams, parameters, throwsClauses, methodBody, annotationMethodDefaultValue), source);

		if (toClearOfMarkers != null) recursiveSetGeneratedBy(toClearOfMarkers, null);
		if (methodArgPos != null) {
			for (int i = 0; i < methodArgPos.length; i++) {
				((JCMethodInvocation) toClearOfMarkers).args.get(i).pos = methodArgPos[i];
			}
		}
		decl.mods.annotations = decl.mods.annotations.appendList(delegates);

		if (addSuppressWarningsUnchecked) {
			ListBuffer<JCExpression> suppressions = new ListBuffer<JCExpression>();
			if (!Boolean.FALSE.equals(field.getAst().readConfiguration(ConfigurationKeys.ADD_SUPPRESSWARNINGS_ANNOTATIONS))) {
				suppressions.append(treeMaker.Literal("all"));
			}
			suppressions.append(treeMaker.Literal("unchecked"));
			addAnnotation(decl.mods, field, source, "java.lang.SuppressWarnings", treeMaker.NewArray(null, List.<JCExpression>nil(), suppressions.toList()));
		}

		copyJavadoc(field, decl, CopyJavadoc.GETTER);
		return decl;
	}

public List<JCAnnotation> findDelegatesAndRemoveFromField(JavacNode field) {

		this.getterErrorNode = field;
		JCVariableDecl fieldNode = (JCVariableDecl) field.get();

		List<JCAnnotation> delegates = List.nil();
		for (JCAnnotation annotation : fieldNode.mods.annotations) {
			if (typeMatches(Delegate.class, field, annotation.annotationType)) {
				delegates = delegates.append(annotation);
			}
		}

		if (!delegates.isEmpty()) {
			ListBuffer<JCAnnotation> withoutDelegates = new ListBuffer<JCAnnotation>();
			for (JCAnnotation annotation : fieldNode.mods.annotations) {
				if (!delegates.contains(annotation)) {
					withoutDelegates.append(annotation);
				}
			}
			fieldNode.mods.annotations = withoutDelegates.toList();
			field.rebuild();
		}
		return delegates;
	}

public List<JCStatement> createSimpleGetterBody(JavacTreeMaker treeMaker, JavacNode field) {
		this.getterTypeNode = field;


		return List.<JCStatement>of(treeMaker.Return(createFieldAccessor(treeMaker, field, FieldAccess.ALWAYS_FIELD)));
	}

private static final String AR = "java.util.concurrent.atomic.AtomicReference";

private static final List<JCExpression> NIL_EXPRESSION = List.nil();

public static final java.util.Map<TypeTag, String> TYPE_MAP;

static {
		Map<TypeTag, String> m = new HashMap<TypeTag, String>();
		m.put(CTC_INT, "Integer");
		m.put(CTC_DOUBLE, "Double");
		m.put(CTC_FLOAT, "Float");
		m.put(CTC_SHORT, "Short");
		m.put(CTC_BYTE, "Byte");
		m.put(CTC_LONG, "Long");
		m.put(CTC_BOOLEAN, "Boolean");
		m.put(CTC_CHAR, "Character");
		TYPE_MAP = Collections.unmodifiableMap(m);
	}

public List<JCStatement> createLazyGetterBody(JavacTreeMaker maker, JavacNode fieldNode, JavacNode source) {
		this.getterTypeNode = fieldNode;
		this.getterErrorNode = source;


		/*
		java.lang.Object value = this.fieldName.get();
		if (value == null) {
			synchronized (this.fieldName) {
				value = this.fieldName.get();
				if (value == null) {
					final RawValueType actualValue = INITIALIZER_EXPRESSION;
					[IF PRIMITIVE]
					value = actualValue;
					[ELSE]
					value = actualValue == null ? this.fieldName : actualValue;
					[END IF]
					this.fieldName.set(value);
				}
			}
		}
		[IF PRIMITIVE]
		return (BoxedValueType) value;
		[ELSE]
		return (BoxedValueType) (value == this.fieldName ? null : value);
		[END IF]
		*/

		ListBuffer<JCStatement> statements = new ListBuffer<JCStatement>();

		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		JCExpression copyOfRawFieldType = copyType(maker, field);
		JCExpression copyOfBoxedFieldType = null;
		field.type = null;
		boolean isPrimitive = false;
		if (field.vartype instanceof JCPrimitiveTypeTree) {
			String boxed = TYPE_MAP.get(typeTag(field.vartype));
			if (boxed != null) {
				isPrimitive = true;
				field.vartype = genJavaLangTypeRef(fieldNode, boxed);
				copyOfBoxedFieldType = genJavaLangTypeRef(fieldNode, boxed);
			}
		}
		if (copyOfBoxedFieldType == null) copyOfBoxedFieldType = copyType(maker, field);

		Name valueName = fieldNode.toName("value");
		Name actualValueName = fieldNode.toName("actualValue");

		/* java.lang.Object value = this.fieldName.get();*/ {
			JCExpression valueVarType = genJavaLangTypeRef(fieldNode, "Object");
			statements.append(maker.VarDef(maker.Modifiers(0L), valueName, valueVarType, callGet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD))));
		}

		/* if (value == null) { */ {
			JCSynchronized synchronizedStatement;
			/* synchronized (this.fieldName) { */ {
				ListBuffer<JCStatement> synchronizedStatements = new ListBuffer<JCStatement>();
				/* value = this.fieldName.get(); */ {
					JCExpressionStatement newAssign = maker.Exec(maker.Assign(maker.Ident(valueName), callGet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD))));
					synchronizedStatements.append(newAssign);
				}

				/* if (value == null) { */ {
					ListBuffer<JCStatement> innerIfStatements = new ListBuffer<JCStatement>();
					/* final RawValueType actualValue = INITIALIZER_EXPRESSION; */ {
						innerIfStatements.append(maker.VarDef(maker.Modifiers(Flags.FINAL), actualValueName, copyOfRawFieldType, field.init));
					}
					/* [IF primitive] value = actualValue; */ {
						if (isPrimitive) {
							JCStatement statement = maker.Exec(maker.Assign(maker.Ident(valueName), maker.Ident(actualValueName)));
							innerIfStatements.append(statement);
						}
					}
					/* [ELSE] value = actualValue == null ? this.fieldName : actualValue; */ {
						if (!isPrimitive) {
							JCExpression actualValueIsNull = maker.Binary(CTC_EQUAL, maker.Ident(actualValueName), maker.Literal(CTC_BOT, null));
							JCExpression thisDotFieldName = createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD);
							JCExpression ternary = maker.Conditional(actualValueIsNull, thisDotFieldName, maker.Ident(actualValueName));
							JCStatement statement = maker.Exec(maker.Assign(maker.Ident(valueName), ternary));
							innerIfStatements.append(statement);
						}
					}
					/* this.fieldName.set(value); */ {
						JCStatement statement = callSet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD), maker.Ident(valueName));
						innerIfStatements.append(statement);
					}

					JCBinary isNull = maker.Binary(CTC_EQUAL, maker.Ident(valueName), maker.Literal(CTC_BOT, null));
					JCIf ifStatement = maker.If(isNull, maker.Block(0, innerIfStatements.toList()), null);
					synchronizedStatements.append(ifStatement);
				}

				synchronizedStatement = maker.Synchronized(createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD), maker.Block(0, synchronizedStatements.toList()));
			}

			JCBinary isNull = maker.Binary(CTC_EQUAL, maker.Ident(valueName), maker.Literal(CTC_BOT, null));
			JCIf ifStatement = maker.If(isNull, maker.Block(0, List.<JCStatement>of(synchronizedStatement)), null);
			statements.append(ifStatement);
		}
		/* [IF PRIMITIVE] return (BoxedValueType) value; */ {
			if (isPrimitive) {
				statements.append(maker.Return(maker.TypeCast(copyOfBoxedFieldType, maker.Ident(valueName))));
			}
		}
		/* [ELSE] return (BoxedValueType) (value == this.fieldName ? null : value); */ {
			if (!isPrimitive) {
				JCExpression valueEqualsSelf = maker.Binary(CTC_EQUAL, maker.Ident(valueName), createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD));
				JCExpression ternary = maker.Conditional(valueEqualsSelf, maker.Literal(CTC_BOT,  null), maker.Ident(valueName));
				JCExpression typeCast = maker.TypeCast(copyOfBoxedFieldType, maker.Parens(ternary));
				statements.append(maker.Return(typeCast));
			}
		}

		// update the field type and init last

		/*	private final java.util.concurrent.atomic.AtomicReference<Object> fieldName = new java.util.concurrent.atomic.AtomicReference<Object>(); */ {
			field.vartype = recursiveSetGeneratedBy(
				maker.TypeApply(chainDotsString(fieldNode, AR), List.<JCExpression>of(genJavaLangTypeRef(fieldNode, "Object"))), source);
			field.init = recursiveSetGeneratedBy(maker.NewClass(null, NIL_EXPRESSION, copyType(maker, field), NIL_EXPRESSION, null), source);
		}

		return statements.toList();
	}

public JCMethodInvocation callGet(JavacNode source, JCExpression receiver) {
		this.getterErrorNode = source;


		JavacTreeMaker maker = source.getTreeMaker();
		return maker.Apply(NIL_EXPRESSION, maker.Select(receiver, source.toName("get")), NIL_EXPRESSION);
	}

public JCStatement callSet(JavacNode source, JCExpression receiver, JCExpression value) {
		this.getterErrorNode = source;


		JavacTreeMaker maker = source.getTreeMaker();
		return maker.Exec(maker.Apply(NIL_EXPRESSION, maker.Select(receiver, source.toName("set")), List.<JCExpression>of(value)));
	}

public static JCExpression copyType(JavacTreeMaker treeMaker, JCVariableDecl fieldNode) {
		return fieldNode.type != null ? treeMaker.Type(fieldNode.type) : fieldNode.vartype;
	}

private static final String SETTER_NODE_NOT_SUPPORTED_ERR = "@Setter is only supported on a class or a field.";

public void generateSetterForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;


		rememberSetterState(typeNode, errorNode, level, checkForTypeLevelSetter, onMethod, onParam);
		if (checkForTypeLevelSetter) {
			if (hasAnnotation(Setter.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return;
			}
		}

		if (!isClass(typeNode)) {
			errorNode.addError(SETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		for (JavacNode field : typeNode.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			//Skip fields that start with $
			if (fieldDecl.name.toString().startsWith("$")) continue;
			//Skip static fields.
			if ((fieldDecl.mods.flags & Flags.STATIC) != 0) continue;
			//Skip final fields.
			if ((fieldDecl.mods.flags & Flags.FINAL) != 0) continue;

			generateSetterForField(field, errorNode, level, onMethod, onParam);
		}
	}

public void generateSetterForField(JavacNode fieldNode, JavacNode sourceNode, AccessLevel level, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterErrorNode = sourceNode;
		this.setterLevel = level;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;


		if (hasAnnotation(Setter.class, fieldNode)) {
			//The annotation will make it happen, so we can skip it.
			return;
		}

		createSetterForField(level, fieldNode, sourceNode, false, onMethod, onParam);
	}

public void handleSetter(AnnotationValues<Setter> annotation, JCAnnotation ast, JavacNode annotationNode) {
		this.setterErrorNode = annotationNode;
		this.setterTypeNode = annotationNode.up();


		handleFlagUsage(annotationNode, ConfigurationKeys.SETTER_FLAG_USAGE, "@Setter");

		Collection<JavacNode> fields = annotationNode.upFromAnnotationToFields();
		deleteAnnotationIfNeccessary(annotationNode, Setter.class);
		deleteImportFromCompilationUnit(annotationNode, "lombok.AccessLevel");
		JavacNode node = annotationNode.up();
		AccessLevel level = annotation.getInstance().value();

		if (level == AccessLevel.NONE || node == null) return;

		List<JCAnnotation> onMethod = unboxAndRemoveAnnotationParameter(ast, "onMethod", "@Setter(onMethod", annotationNode);
		List<JCAnnotation> onParam = unboxAndRemoveAnnotationParameter(ast, "onParam", "@Setter(onParam", annotationNode);

		switch (node.getKind()) {
		case FIELD:
			createSetterForFields(level, fields, annotationNode, true, onMethod, onParam);
			break;
		case TYPE:
			generateSetterForType(node, annotationNode, level, false, onMethod, onParam);
			break;
		}
	}

public void createSetterForFields(AccessLevel level, Collection<JavacNode> fieldNodes, JavacNode errorNode, boolean whineIfExists, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterLevel = level;
		this.setterErrorNode = errorNode;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;


		for (JavacNode fieldNode : fieldNodes) {
			createSetterForField(level, fieldNode, errorNode, whineIfExists, onMethod, onParam);
		}
	}

public void createSetterForField(AccessLevel level, JavacNode fieldNode, JavacNode sourceNode, boolean whineIfExists, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterLevel = level;
		this.setterErrorNode = sourceNode;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;


		if (fieldNode.getKind() != Kind.FIELD) {
			fieldNode.addError(SETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();
		String methodName = toSetterName(fieldNode);

		if (methodName == null) {
			fieldNode.addWarning("Not generating setter for this field: It does not fit your @Accessors prefix list.");
			return;
		}

		if ((fieldDecl.mods.flags & Flags.FINAL) != 0) {
			fieldNode.addWarning("Not generating setter for this field: Setters cannot be generated for final fields.");
			return;
		}

		for (String altName : toAllSetterNames(fieldNode)) {
			switch (methodExists(altName, fieldNode, false, 1)) {
			case EXISTS_BY_LOMBOK:
				return;
			case EXISTS_BY_USER:
				if (whineIfExists) {
					String altNameExpl = "";
					if (!altName.equals(methodName)) altNameExpl = String.format(" (%s)", altName);
					fieldNode.addWarning(
						String.format("Not generating %s(): A method with that name already exists%s", methodName, altNameExpl));
				}
				return;
			default:
			case NOT_EXISTS:
				//continue scanning the other alt names.
			}
		}

		long access = toJavacModifier(level) | (fieldDecl.mods.flags & Flags.STATIC);

		JCMethodDecl createdSetter = createSetter(access, fieldNode, fieldNode.getTreeMaker(), sourceNode, onMethod, onParam);
		injectMethod(fieldNode.up(), createdSetter);
	}

public JCMethodDecl createSetter(long access, JavacNode field, JavacTreeMaker treeMaker, JavacNode source, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {

		this.setterErrorNode = source;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		String setterName = toSetterName(field);
		boolean returnThis = shouldReturnThis(field);
		return createSetter(access, false, field, treeMaker, setterName, null, null, returnThis, source, onMethod, onParam);
	}

public JCMethodDecl createSetter(long access, boolean deprecate, JavacNode field, JavacTreeMaker treeMaker, String setterName, Name paramName, Name booleanFieldToSet, boolean shouldReturnThis, JavacNode source, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {

		this.setterErrorNode = source;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		JCExpression returnType = null;
		JCReturn returnStatement = null;
		if (shouldReturnThis) {
			returnType = cloneSelfType(field);
			returnStatement = treeMaker.Return(treeMaker.Ident(field.toName("this")));
		}

		JCMethodDecl d = createSetter(access, deprecate, field, treeMaker, setterName, paramName, booleanFieldToSet, returnType, returnStatement, source, onMethod, onParam);
		if (shouldReturnThis && getCheckerFrameworkVersion(source).generateReturnsReceiver()) {
			List<JCAnnotation> annotations = d.mods.annotations;
			if (annotations == null) annotations = List.nil();
			JCAnnotation anno = treeMaker.Annotation(genTypeRef(source, CheckerFrameworkVersion.NAME__RETURNS_RECEIVER), List.<JCExpression>nil());
			recursiveSetGeneratedBy(anno, source);
			d.mods.annotations = annotations.prepend(anno);
		}
		return d;
	}

